let memory = {};
const readStorage = (key, fallback) => { try { return JSON.parse(localStorage.getItem(`dollarone-${key}`)) ?? fallback; } catch { return memory[key] ?? fallback; } };
const writeStorage = (key, value) => { memory[key] = value; try { localStorage.setItem(`dollarone-${key}`,JSON.stringify(value)); } catch { showToast('เบราว์เซอร์ไม่อนุญาตให้บันทึก แผนนี้จะเก็บไว้เฉพาะรอบใช้งานนี้'); } };
let plan = readStorage('plan',[]); if(!Array.isArray(plan)) plan=[]; plan = [...new Set(plan)].filter(id=>courses.some(c=>c.id===id));
let filters = {category:'all',role:'all',search:''};
let currentRoute = '';
function hydrateIcons(){ $$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon)); }
function updatePlanCount(){ const count=$('#plan-count'); count.textContent=plan.length;count.hidden=!plan.length; }
function showToast(message){ const el=$('#toast'); el.textContent=message;el.classList.add('show');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.remove('show'),3500); }
function art(c){return `<div class="course-art ${c.color}"><span class="art-kicker">DOLLARONE ACADEMY / ${esc(c.categoryLabel.toUpperCase())}</span><span class="art-num">${String(courses.indexOf(c)+1).padStart(2,'0')}</span><span class="art-title">${esc(c.en).replace(/\n/g,'<br>')}</span><span class="art-bottom">LEARN WITH PURPOSE. GROW WITH CONFIDENCE.</span><span class="art-shape"></span></div>`;}
function courseCard(c){return `<article class="course-card"><button class="course-art-button" style="padding:0;border:0" data-course="${c.id}" aria-label="ดูหลักสูตร ${esc(c.title)}">${art(c)}</button><div class="course-card-content"><div class="course-tags"><span class="pill">${c.categoryLabel}</span><span class="pill pending">เตรียมเปิดสอน</span></div><h3><button data-course="${c.id}">${c.title}</button></h3><p>${c.desc}</p><div class="course-meta"><span>${icon('clock')}แผน ${c.hours} ชั่วโมง</span><span>${icon(c.mode==='Online'?'play':'users')}${c.mode}</span></div><div class="course-card-bottom"><small>รายละเอียดหลักสูตรตัวอย่าง</small><button data-course="${c.id}">ดูรายละเอียด <span>↗</span></button></div></div></article>`;}
function serviceCard(s,i){return `<a class="service-card" href="#/services/${s.id}"><div class="service-card-top"><span class="service-icon">${icon(s.icon)}</span><small>0${i+1}</small></div><h3>${s.title}</h3><p>${s.text}</p><div class="service-bottom">${s.name}<span>↗</span></div></a>`;}
function resourceCard(a){return `<a class="resource-card" href="#/insights/${a.id}"><div class="resource-art ${a.art}"><div class="paper"></div><span class="tag">${a.tag}</span></div><div class="resource-category">${a.category} <span> / ${a.reading} MIN READ</span></div><h3>${a.title}</h3><p>${a.desc}</p><span class="text-link">อ่านต่อ <span>↗</span></span></a>`;}
function cpdBanner(){return `<div class="cpd-banner"><div class="cpd-graphic"><div class="hour-ring"><span>↗</span></div><div><strong>YOUR NEXT<br>PROFESSIONAL STEP.</strong><small>เริ่มวางแผนการเรียนรู้ของคุณ</small></div></div><div><h3>เตรียมพร้อมสำหรับก้าวต่อไปในวิชาชีพ</h3><p>จัดแผนการเรียนและบันทึกชั่วโมงที่คุณมีหลักฐานรับรองแล้ว</p></div><a class="btn btn-orange" href="#/cpd">วางแผนชั่วโมงอบรม <span>↗</span></a></div>`;}
function contactBanner(){return `<div class="container"><div class="next-chapter"><div><div class="eyebrow">LET'S GROW TOGETHER</div><h2>ก้าวต่อไปของคุณ เริ่มที่บทสนทนาดี ๆ</h2><p>เล่าเป้าหมายของธุรกิจ หรือเส้นทางการเรียนรู้ที่คุณกำลังมองหา</p></div><button class="btn btn-dark" data-contact>เริ่มคุยกับ DollarOne <span>↗</span></button></div></div>`;}
function pageHero(eyebrow,title,description,dark=false){return `<section class="page-hero ${dark?'dark':''}"><div class="container"><div class="breadcrumbs"><a href="#/">หน้าแรก</a><span>/</span><span>${title}</span></div><div class="eyebrow ${dark?'orange':''}">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div></section>`;}
function renderHome(){return `<section class="hero"><div class="container"><div class="hero-inner"><div class="hero-copy"><div class="eyebrow">YOUR PARTNER IN BUSINESS & PROFESSIONAL GROWTH</div><h1>ธุรกิจไปต่อ<br>ความรู้<em>ไปไกล</em></h1><p class="hero-description">ให้เรื่องบัญชีและภาษีเป็นเรื่องที่เข้าใจง่าย<br>พร้อมเติมความรู้ให้คุณก้าวต่อได้อย่างมั่นใจ<br>ทุกการเติบโต เริ่มต้นที่ DollarOne</p><div class="hero-buttons"><a class="btn btn-orange" href="#/services">ให้เราดูแลธุรกิจคุณ <span>↗</span></a><a class="btn btn-outline" href="#/academy">ค้นหาคอร์สที่ใช่ <span>↗</span></a></div><div class="hero-note">${icon('check')} สำหรับเจ้าของธุรกิจ นักบัญชี และผู้ประกอบวิชาชีพ</div></div><div class="hero-visual" role="img" aria-label="ภาพแนวคิดการดูแลบัญชีและการเรียนรู้ ข้อมูลการเงินเป็นข้อมูลสมมติ"><div class="orb"></div><div class="orbit"></div><div class="workspace"><div class="workspace-top"><i></i><i></i><i></i><span>DOLLARONE / BUSINESS IN BALANCE</span></div><div class="workspace-body"><div class="workspace-side"><span class="mini-brand">d1</span>${icon('grid')}${icon('chart')}${icon('document')}${icon('users')}</div><div class="workspace-chart"><span class="mini-overline">ภาพรวมธุรกิจ · ข้อมูลตัวอย่าง</span><div class="mini-chart-header"><strong>฿128,450<span style="display:none"></span></strong><span>↗ 12.8%</span></div><div class="bars">${[29,42,35,56,47,65,58,79,73,91,100,115].map(h=>`<div class="bar" style="height:${Math.round(h*.8)}%"></div>`).join('')}</div><div class="bar-labels"><span>JAN</span><span>FEB</span><span>MAR</span><span>APR</span><span>MAY</span><span>JUN</span></div><div class="chart-bottom"><span>บัญชีเป็นระบบ<b>Organized.</b></span><span>มองเห็นภาพธุรกิจ<b>Understood.</b></span><span>พร้อมเติบโต<b>Ready to grow.</b></span></div></div></div></div><div class="float-card tax-card"><span class="check">${icon('check')}</span><div><b>เรื่องภาษี มีคนช่วยคิด</b><small>MORE CLARITY. LESS WORRY.</small></div></div><div class="float-card academy-float"><span class="float-icon">${icon('graduation')}</span><div><b>DOLLARONE ACADEMY</b><p>เติมความรู้ ต่อยอดทุกโอกาส</p></div></div><span class="visual-star">✳</span><small class="visual-note">ภาพแสดงแนวคิดบริการ · ข้อมูลสมมติ</small></div></div><div class="hero-strip">${[['calculator','บัญชีที่เข้าใจธุรกิจ','ACCOUNTING'],['shield','ภาษีที่วางแผนได้','TAX & COMPLIANCE'],['graduation','พัฒนาทักษะวิชาชีพ','PROFESSIONAL LEARNING'],['users','เติบโตไปด้วยกัน','BUSINESS PARTNERSHIP']].map(x=>`<div class="hero-strip-item">${icon(x[0])}<div>${x[1]}<span>${x[2]}</span></div></div>`).join('')}</div></div></section>
<section class="section container"><div class="section-heading"><div><div class="eyebrow">BUILT FOR YOUR BUSINESS</div><h2>คุณโฟกัสที่ธุรกิจ<br>ให้เราช่วยดูแลเรื่องตัวเลข</h2><p>เริ่มธุรกิจ วางระบบ หรือเติบโตต่อ เราพร้อมเป็นส่วนหนึ่งในทุกจังหวะ</p></div><a href="#/services" class="text-link">สำรวจบริการของเรา <span>↗</span></a></div><div class="section-caption"><span>OUR EXPERTISE / YOUR PEACE OF MIND</span><span>ACCOUNTING · TAX · BUSINESS · ADVISORY</span></div><div class="service-grid">${serviceData.map(serviceCard).join('')}</div><div class="service-footer">ยังไม่แน่ใจว่าธุรกิจของคุณเหมาะกับบริการไหน? <button data-contact>เริ่มจากเล่าให้เราฟังก่อน ↗</button></div></section>
<section class="section academy-section"><div class="container"><div class="section-heading"><div><div class="eyebrow">A LITTLE MORE KNOWLEDGE. A LOT MORE POSSIBILITY.</div><h2 class="academy-title"><span class="academy-logo">DollarOne <span>Academy</span></span><small>YOUR NEXT LEVEL</small></h2><p>พัฒนาความรู้บัญชี ภาษี และทักษะวิชาชีพ ให้พร้อมกับโอกาสใหม่</p></div><a class="text-link" href="#/academy">ค้นพบทุกหลักสูตร <span>↗</span></a></div><div class="filter-row"><div class="filter-tabs" aria-label="หมวดหลักสูตรแนะนำ">${[['all','คอร์สแนะนำ'],['accounting','บัญชี'],['tax','ภาษี'],['professional','พัฒนาวิชาชีพ']].map((x,i)=>`<button class="filter-btn ${i===0?'active':''}" data-home-category="${x[0]}" aria-pressed="${i===0}">${x[1]}</button>`).join('')}</div></div><div class="course-grid" id="home-courses">${courses.slice(0,3).map(courseCard).join('')}</div><p class="academy-disclaimer">${icon('info')}${CPD_NOTE}</p>${cpdBanner()}</div></section>
<section class="section container"><div class="section-heading"><div><div class="eyebrow">THE KNOWLEDGE CORNER</div><h2>เรื่องที่รู้แล้ว ธุรกิจไปต่อได้ง่ายขึ้น</h2><p>มุมมอง เช็กลิสต์ และแนวทางเริ่มต้นสำหรับคนทำธุรกิจและนักบัญชี</p></div><a class="text-link" href="#/insights">เปิดคลังความรู้ <span>↗</span></a></div><div class="resources-grid">${articles.map(resourceCard).join('')}</div></section>${contactBanner()}`;}
function renderServices(id){ const selected=serviceData.find(s=>s.id===id);return `${pageHero('ACCOUNTING. TAX. PEACE OF MIND.',selected?selected.title:'ดูแลเรื่องตัวเลข เพื่อทุกก้าวของธุรกิจ',selected?selected.text:'เลือกความช่วยเหลือให้ตรงกับช่วงของธุรกิจ แล้วกำหนดขอบเขตงานที่ชัดเจนไปด้วยกัน')}<section class="container section">${selected?`<div class="detail-intro"><div><div class="eyebrow">${selected.en}</div><h2>${selected.name}</h2><p style="margin-top:20px">ทุกธุรกิจมีวิธีทำงานต่างกัน เราเริ่มต้นจากความเข้าใจรูปแบบกิจการ ปริมาณเอกสาร และเป้าหมายของคุณ เพื่อวางขอบเขตงานที่เหมาะสม</p><button class="btn btn-orange" style="margin-top:25px" data-contact="${selected.title}">เตรียมข้อมูลเพื่อปรึกษา <span>↗</span></button></div><div class="panel"><h3>ขอบเขตบริการเบื้องต้น</h3><ul class="check-list">${selected.details.map(t=>`<li>${icon('check')}${t}</li>`).join('')}</ul><p class="small-muted" style="margin-top:20px">รายละเอียด ค่าใช้จ่าย และผู้รับผิดชอบวิชาชีพต้องยืนยันก่อนทำสัญญาให้บริการ</p></div></div>`:`<div class="service-grid">${serviceData.map(serviceCard).join('')}</div>`}<div style="margin-top:55px"><div class="eyebrow">A CLEAR WAY FORWARD</div><h2>เริ่มต้นแบบเข้าใจตรงกัน</h2><div class="process"><article><b>01</b><h3>เล่าเรื่องธุรกิจของคุณ</h3><p>เตรียมข้อมูลรูปแบบกิจการ ปริมาณรายการ และสิ่งที่ต้องการให้ช่วยดูแล</p></article><article><b>02</b><h3>กำหนดขอบเขตให้ชัด</h3><p>ทบทวนเอกสาร ผู้รับผิดชอบ ระยะเวลา และค่าใช้จ่าย ก่อนตัดสินใจใช้บริการ</p></article><article><b>03</b><h3>เริ่มงานอย่างเป็นระบบ</h3><p>วางขั้นตอนส่งต่อข้อมูลและช่องทางติดตามงานร่วมกันตามข้อตกลง</p></article></div></div><div class="notice">หน้านี้เป็นแนวคิดบริการสำหรับเว็บไซต์ต้นแบบ ยังไม่ใช่ข้อเสนอหรือสัญญาให้บริการ และยังไม่เปิดรับเอกสารบัญชีจริง</div></section>${contactBanner()}`; }
function renderAcademy(){return `${pageHero('DOLLARONE ACADEMY / LEARN WITH PURPOSE.','ความรู้ที่ต่อยอดคุณได้จริง','ค้นหาหลักสูตรบัญชี ภาษี และเครื่องมือทำงาน เลือกเรียนให้ตรงกับเป้าหมายและเส้นทางวิชาชีพของคุณ',true)}<section class="container academy-catalog"><div class="filter-row"><div class="filter-tabs" aria-label="หมวดหลักสูตร">${[['all','ทั้งหมด'],['accounting','บัญชี'],['tax','ภาษี'],['professional','พัฒนาวิชาชีพ'],['tools','เครื่องมือทำงาน']].map(x=>`<button class="filter-btn ${filters.category===x[0]?'active':''}" data-category="${x[0]}" aria-pressed="${filters.category===x[0]}">${x[1]}</button>`).join('')}</div><label class="searchbox">${icon('search')}<input id="course-search" type="search" placeholder="ค้นหาคอร์ส เช่น ภาษี, Excel, งบการเงิน" aria-label="ค้นหาหลักสูตร" value="${esc(filters.search)}"></label></div><div style="display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:22px;flex-wrap:wrap"><span class="small-muted" id="result-count" role="status"></span><label class="small-muted">เป้าหมายผู้เรียน <select id="role-filter" style="padding:6px 10px;margin-left:8px;border:1px solid #d1d7c2;border-radius:5px;background:#fffefa;font-size:11px"><option value="all">ทุกเส้นทาง</option><option value="business">เจ้าของธุรกิจ</option><option value="accountant">ผู้ทำบัญชี</option><option value="cpa">CPA</option><option value="ta">TA</option></select></label></div><div id="catalog-courses" class="course-grid"></div><p class="academy-disclaimer">${icon('info')}${CPD_NOTE} · ตัวกรองวิชาชีพหมายถึงกลุ่มผู้เรียนที่เนื้อหาเหมาะสม ไม่ใช่สิทธิการนับชั่วโมง</p>${cpdBanner()}</section>`;}
function filterCatalog(){const list=courses.filter(c=>(filters.category==='all'||c.category===filters.category)&&(filters.role==='all'||c.roles.includes(filters.role))&&`${c.title} ${c.desc} ${c.en} ${c.categoryLabel}`.toLowerCase().includes(filters.search.toLowerCase().trim()));const grid=$('#catalog-courses');if(!grid)return;grid.innerHTML=list.length?list.map(courseCard).join(''):`<div class="empty-state">${icon('search')}<h2>ยังไม่พบคอร์สที่ตรงกับคำค้น</h2><p>ลองเปลี่ยนคำค้น หรือเลือกหมวดและเส้นทางอื่น</p><button class="btn btn-line" id="clear-filters">ล้างตัวกรองทั้งหมด</button></div>`;$('#result-count').textContent=`พบ ${list.length} หลักสูตรตัวอย่าง`;$('[id="role-filter"]').value=filters.role;}
function renderLearning(){const selected=courses.filter(c=>plan.includes(c.id));return `${pageHero('YOUR LEARNING JOURNEY','แผนการเรียนของฉัน','บันทึกคอร์สที่สนใจ แล้วค่อย ๆ วางเส้นทางการพัฒนาของคุณ แผนนี้เก็บไว้ในเบราว์เซอร์เครื่องนี้เท่านั้น')}<section class="container section">${selected.length?`<div class="section-caption"><span>YOUR NEXT CHAPTER / ${selected.length} COURSES</span><span>แผนนี้ยังไม่ใช่การสมัครเรียน</span></div>${selected.map(c=>`<article class="plan-card">${art(c)}<div><span class="pill">${c.categoryLabel}</span><h3>${c.title}</h3><p class="small-muted">${c.mode} · แผนการสอน ${c.hours} ชั่วโมง · ยังไม่รับรอง CPD</p><button class="text-link" data-lesson="${c.id}">ทดลองบทเรียน <span>↗</span></button></div><button class="remove-course" data-remove="${c.id}" aria-label="นำ ${c.title} ออกจากแผน">×</button></article>`).join('')}<a class="btn btn-line" href="#/academy">เพิ่มหลักสูตรในแผน <span>+</span></a>`:`<div class="empty-state">${icon('bookmark')}<h2>ทุกก้าว เริ่มจากความสนใจ</h2><p>ค้นพบคอร์สที่อยากเรียน แล้วกด “เพิ่มในแผนการเรียน”</p><a class="btn btn-orange" href="#/academy">สำรวจหลักสูตร <span>↗</span></a></div>`}<div class="plan-info">${icon('info')}<div><h3>ชั่วโมงเรียนกับชั่วโมงที่นับได้ ต้องแยกกัน</h3><p>การเพิ่มคอร์สหรือทดลองบทเรียนไม่ทำให้ได้รับชั่วโมงรับรอง CPD หรือใบประกาศนียบัตร</p><a class="text-link" href="#/cpd" style="margin-top:10px">ไปวางแผนชั่วโมงที่มีหลักฐานรับรอง <span>↗</span></a></div></div></section>`;}
function renderCpd(){let p=readStorage('cpd',{});if(!p||typeof p!=='object')p={};return `${pageHero('MAKE ROOM FOR YOUR NEXT STEP.','วางแผนชั่วโมงอบรม','ตั้งเป้าหมายส่วนตัวและติดตามชั่วโมงที่คุณมีหลักฐานแล้ว ตรวจหลักเกณฑ์ปัจจุบันกับหน่วยงานที่กำกับก่อนใช้อ้างอิงเสมอ')}<section class="container section"><div class="planner-layout"><form class="panel" id="cpd-form"><h2>แผนพัฒนาความรู้ของคุณ</h2><p>เครื่องมือนี้คำนวณจากตัวเลขที่คุณกรอก ไม่ตรวจรับรองชั่วโมงหรือยื่นข้อมูลแทนคุณ</p><label class="field">เส้นทางวิชาชีพ<select id="cpd-role"><option value="accountant">ผู้ทำบัญชี</option><option value="cpa">ผู้สอบบัญชีรับอนุญาต (CPA)</option><option value="ta">ผู้สอบบัญชีภาษีอากร (TA)</option><option value="other">ผู้สนใจพัฒนาความรู้</option></select></label><label class="field">ปีที่วางแผน (พ.ศ.)<input id="cpd-year" type="number" min="2500" max="2700" required value="${Number.isFinite(Number(p.year))&&p.year?Number(p.year):2569}"></label><div class="field-row"><label class="field">เป้าหมายที่คุณตรวจสอบแล้ว (ชม.)<input id="cpd-target" type="number" min="0.5" max="1000" step="0.5" required placeholder="เช่น 20" value="${Number(p.target)>0?Number(p.target):''}"></label><label class="field">ชั่วโมงที่มีหลักฐานแล้ว (ชม.)<input id="cpd-done" type="number" min="0" max="1000" step="0.5" required placeholder="เช่น 6" value="${Number(p.done)>=0&&p.done!==undefined?Number(p.done):''}"></label></div><span class="field-hint">เป้าหมายต้องพิจารณาหมวดวิชา รูปแบบอบรม และเงื่อนไขเฉพาะวิชาชีพด้วย</span><button class="btn btn-dark" type="submit">บันทึกแผนในเบราว์เซอร์ <span>↗</span></button><p class="small-muted" style="margin-top:13px">ไม่เก็บชื่อ เลขทะเบียนวิชาชีพ หรือเอกสารส่วนตัว</p></form><div><div class="panel" id="cpd-summary" aria-live="polite"></div><div class="notice">การแสดงผลนี้เป็นเพียงความก้าวหน้าเทียบเป้าหมายส่วนตัว ไม่ยืนยันว่าครบตามเกณฑ์วิชาชีพ หลักสูตร DollarOne ในต้นแบบยังไม่ให้ชั่วโมงที่รับรอง</div><div style="padding:25px 4px"><h3 style="font-size:15px">ตรวจหลักเกณฑ์จากแหล่งทางการ</h3>${officialLinks()}<p class="small-muted" style="margin-top:15px">ผู้ทำบัญชี: DBD / CPA: TFAC / TA: กรมสรรพากร</p></div></div></div></section>`;}
function updateCpdSummary(){const t=Number($('#cpd-target').value),d=Number($('#cpd-done').value);const valid=$('#cpd-target').value!==''&&$('#cpd-done').value!==''&&t>0&&t<=1000&&d>=0&&d<=1000;$('#cpd-summary').innerHTML=valid?`<div class="eyebrow">YOUR PERSONAL PROGRESS</div><h2>ค่อย ๆ เติมให้ถึงเป้าหมาย</h2><div class="progress-number">${d.toLocaleString('th-TH')}<small> / ${t.toLocaleString('th-TH')} ชั่วโมง</small></div><div class="progress-bar" role="progressbar" aria-label="ชั่วโมงเทียบเป้าหมายส่วนตัว" aria-valuemin="0" aria-valuemax="${t}" aria-valuenow="${Math.min(d,t)}"><div style="width:${Math.min(100,d/t*100)}%"></div></div><div class="progress-caption"><span>${Math.round(d/t*100)}% ของเป้าหมายส่วนตัว</span><span>เหลือ ${Math.max(0,t-d)} ชม.</span></div><p style="margin-top:22px">${d>=t?'ถึงเป้าหมายที่ตั้งไว้แล้ว กรุณาตรวจหมวดและหลักฐานให้ตรงกับเกณฑ์ที่เกี่ยวข้อง':'แบ่งเวลาเรียนให้เหมาะกับตารางงาน และตรวจสิทธิการนับชั่วโมงก่อนเลือกอบรม'}</p>`:`<div class="eyebrow">YOUR PERSONAL PROGRESS</div><h2>ตั้งเป้าหมายให้ก้าวต่อได้ชัดขึ้น</h2><p>กรอกเป้าหมายที่ตรวจสอบแล้ว และจำนวนชั่วโมงที่คุณมีหลักฐาน เพื่อดูความก้าวหน้าของแผน</p><div class="progress-number" style="color:#b5bdab">—<small> ชั่วโมง</small></div>`;}
function renderInsights(id){const a=articles.find(x=>x.id===id);if(!a)return `${pageHero('THE KNOWLEDGE CORNER','คลังความรู้ของคนทำธุรกิจ','ความรู้เบื้องต้นที่ช่วยจัดระบบความคิดและเตรียมคำถามก่อนเริ่มงานกับผู้เชี่ยวชาญ')}<section class="container section"><div class="resources-grid">${articles.map(resourceCard).join('')}</div></section>${contactBanner()}`;let body='';if(a.id==='business-documents')body=`<p>การส่งงานบัญชีเริ่มได้จากระบบจัดเก็บเอกสารที่ทั้งเจ้าของธุรกิจและผู้ทำบัญชีเข้าใจตรงกัน รายการนี้เป็นแนวทางทั่วไป ควรปรับกับรูปแบบและรายการจริงของกิจการ</p><h2>เริ่มจากข้อมูลพื้นฐานของกิจการ</h2><ul><li>ข้อมูลจดทะเบียนและข้อมูลติดต่อของผู้รับผิดชอบ</li><li>ข้อมูลบัญชีธนาคารที่ใช้สำหรับธุรกิจ</li><li>รายการบริการหรือสินค้าที่กิจการดำเนินการ</li><li>สถานะการจดทะเบียนภาษีที่เกี่ยวข้อง</li></ul><h2>จัดกลุ่มเอกสารรายเดือน</h2><p>แยกเอกสารขาย เอกสารซื้อ รายการรับจ่าย และข้อมูลเงินเดือนตามเดือนที่เกิดรายการ ตั้งชื่อไฟล์ให้ค้นหาได้ และตกลงวันที่ส่งข้อมูลร่วมกับผู้ทำบัญชี</p><h2>ส่งข้อมูลผ่านช่องทางที่ตกลงกัน</h2><p>เลือกช่องทางส่งเอกสารที่ควบคุมสิทธิการเข้าถึงได้ ตรวจผู้รับทุกครั้ง และหลีกเลี่ยงการส่งข้อมูลส่วนตัวหรือข้อมูลการเงินผ่านช่องทางสาธารณะ</p>`;
if(a.id==='cpd-planning')body=`<p>ก่อนเลือกหลักสูตร ควรเริ่มจากการระบุสถานะวิชาชีพของตนเอง เพราะการพัฒนาความรู้ต่อเนื่องและการต่ออายุใบอนุญาตมีหน่วยงานและเงื่อนไขที่ต่างกัน</p><h2>แยกเส้นทางให้ถูกก่อนเลือกเรียน</h2><ul><li>ผู้ทำบัญชี: ตรวจหลักเกณฑ์และระบบที่กรมพัฒนาธุรกิจการค้ากำหนด</li><li>ผู้สอบบัญชีรับอนุญาต (CPA): ตรวจหลักเกณฑ์ CPD กับสภาวิชาชีพบัญชี</li><li>ผู้สอบบัญชีภาษีอากร (TA): ตรวจหลักเกณฑ์การอบรมและต่ออายุที่กรมสรรพากรกำหนด</li></ul><h2>ตรวจหลักสูตรเป็นรายกรณี</h2><p>สอบถามผู้จัดเรื่องสถานะการได้รับความเห็นชอบ เลขที่อนุมัติหลักสูตร กลุ่มวิชาชีพที่นับได้ หมวดชั่วโมง รูปแบบอบรม เงื่อนไขการเข้าร่วม และหลักฐานที่จะได้รับ การมีใบประกาศอย่างเดียวไม่ยืนยันสิทธิการนับชั่วโมงทุกกรณี</p><h2>เก็บหลักฐานและตรวจยอดของตนเอง</h2><p>เก็บรายละเอียดหลักสูตร หลักฐานการเข้าเรียน และข้อมูลการแจ้งชั่วโมง ตรวจสอบความครบถ้วนกับระบบของหน่วยงานที่เกี่ยวข้องก่อนถึงกำหนด</p><h2>แหล่งข้อมูลทางการ</h2>${officialLinks()}<div class="notice">เนื้อหานี้เป็นแนวทางวางแผน ไม่ระบุตัวเลขชั่วโมงขั้นต่ำเพื่อหลีกเลี่ยงการใช้เกณฑ์ผิดประเภทหรือผิดรอบปี โปรดตรวจข้อกำหนดล่าสุดของคุณโดยตรง</div><a class="btn btn-orange" style="margin-top:25px;text-decoration:none;color:#151819" href="#/cpd">ไปวางแผนของฉัน <span>↗</span></a>`;
if(a.id==='monthly-checklist')body=`<p>งานบัญชีที่ติดตามได้ง่ายเริ่มจากกิจวัตรเล็ก ๆ ที่ทำอย่างสม่ำเสมอ ใช้เช็กลิสต์นี้เป็นต้นทาง แล้วปรับกำหนดเวลาตามข้อตกลงกับผู้ดูแลงานของกิจการ</p><h2>รวบรวมและแยกรายการ</h2><ul><li>ตรวจว่ามีเอกสารประกอบรายการขายและรายการซื้อครบถ้วน</li><li>แยกรายการธุรกิจออกจากรายการส่วนตัว</li><li>ตรวจใบเสร็จ เอกสารรับเงิน และหลักฐานโอนให้ตรงกัน</li><li>สรุปรายการค้างรับ ค้างจ่าย และเอกสารที่ยังขาด</li></ul><h2>ทบทวนกับรายการธนาคาร</h2><p>ไล่เทียบรายการรับจ่ายกับรายการเดินบัญชี จดรายการที่ยังหาที่มาไม่ได้ และตั้งผู้รับผิดชอบติดตาม การพบข้อแตกต่างเร็วช่วยลดการย้อนค้นในช่วงปิดบัญชี</p><h2>สื่อสารก่อนส่งงาน</h2><p>แนบรายการที่มีข้อสงสัย พร้อมข้อมูลที่มีจริงให้ผู้ทำบัญชีพิจารณา ติดตามกำหนดที่เกี่ยวข้องจากแหล่งทางการและผู้รับผิดชอบ โดยไม่ใช้รายการทั่วไปแทนปฏิทินภาษีของกิจการ</p>`;
return `${pageHero(a.category,a.title,`บทความเบื้องต้น · อ่านประมาณ ${a.reading} นาที`)}<div class="container"><article class="article-body">${body}<div class="notice">เนื้อหาตัวอย่างสำหรับเว็บไซต์ต้นแบบ เป็นข้อมูลทั่วไป ควรตรวจข้อเท็จจริงและกฎที่ใช้กับกิจการของคุณก่อนดำเนินการ</div><a class="text-link" style="margin-top:30px;text-decoration:none" href="#/insights">← กลับไปคลังความรู้</a></article></div>`;}
function renderAbout(){return `${pageHero('ONE PARTNER. EVERY STEP.','รู้จัก DollarOne','จุดเริ่มต้นของแนวคิดที่อยากให้เรื่องบัญชี ภาษี และการเรียนรู้ เข้าถึงง่ายขึ้น')}<div class="container"><div class="about-banner">Business grows.<br><span>Knowledge flows.</span></div><div class="detail-intro" style="padding-top:0"><div><div class="eyebrow">WHY DOLLARONE</div><h2>เข้าใจธุรกิจ<br>ไปพร้อมกับพัฒนาคน</h2></div><div><p>DollarOne เป็นแนวคิดแบรนด์ที่รวมสองสิ่งไว้ด้วยกัน: ความช่วยเหลือด้านบัญชีและภาษีสำหรับเจ้าของธุรกิจ และพื้นที่พัฒนาความรู้สำหรับคนทำงานบัญชีและผู้ประกอบวิชาชีพ</p><p style="margin-top:18px">เราออกแบบให้คนเริ่มธุรกิจเลือกบริการได้ง่าย และคนที่อยากเติบโตในวิชาชีพมองเห็นเส้นทางเรียนรู้ของตนเอง ภายใต้ประสบการณ์และชื่อแบรนด์เดียวกัน</p></div></div><div class="notice" style="margin-bottom:50px">DollarOne อยู่ในขั้นพัฒนาแนวคิด ยังไม่ได้จดโดเมนตามชื่อแบรนด์ ข้อมูลนิติบุคคล ทีมงาน คุณสมบัติผู้ให้บริการ และการรับรองหลักสูตรจะต้องยืนยันก่อนเปิดให้บริการจริง</div><div class="faq-wrap"><div class="eyebrow">GOOD QUESTIONS. CLEAR ANSWERS.</div><h2>รู้จักเราให้มากขึ้น</h2>${faqs.slice(0,4).map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div>${contactBanner()}`;}
function renderFaq(){return `${pageHero('GOOD QUESTIONS. CLEAR ANSWERS.','คำถามที่พบบ่อย','ข้อมูลสำคัญเกี่ยวกับบริการ Academy และการใช้งานเว็บไซต์ต้นแบบ')}<div class="container"><div class="faq-wrap">${faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div>`;}
function route(){const hash=location.hash||'#/';if(hash==='#main'){$('#main').focus();return;}const [routeName,id]=hash.replace(/^#\/?/,'').split('/');if(routeName==='academy'&&currentRoute!=='academy')filters={category:'all',role:'all',search:''};currentRoute=routeName||'home';const pages={home:()=>renderHome(),services:()=>renderServices(id),academy:renderAcademy,learning:renderLearning,cpd:renderCpd,insights:()=>renderInsights(id),about:renderAbout,faq:renderFaq};const render=pages[currentRoute];$('#main').innerHTML=render?render():`${pageHero('LET’S FIND YOUR WAY.','ไม่พบหน้าที่คุณต้องการ','ลองกลับไปหน้าแรก หรือเลือกเมนูที่ต้องการ')}<div class="container section"><a class="btn btn-orange" href="#/">กลับหน้าแรก <span>↗</span></a></div>`;const titles={home:'ธุรกิจไปต่อ ความรู้ไปไกล',services:'บริการบัญชีและภาษี',academy:'Academy — ทุกหลักสูตร',learning:'แผนการเรียนของฉัน',cpd:'วางแผนชั่วโมงอบรม',insights:'คลังความรู้',about:'รู้จักเรา',faq:'คำถามที่พบบ่อย'};document.title=`DollarOne — ${titles[currentRoute]||'ไม่พบหน้า'}`;$$('[data-nav]').forEach(a=>{const active=a.dataset.nav===currentRoute;a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});$('#navigation').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');$('#menu-toggle').setAttribute('aria-label','เปิดเมนู');if($('#modal').open)$('#modal').close();if(currentRoute==='academy')filterCatalog();if(currentRoute==='cpd'){const p=readStorage('cpd',{});if(p&&['accountant','cpa','ta','other'].includes(p.role))$('#cpd-role').value=p.role;updateCpdSummary();}hydrateIcons();window.scrollTo({top:0,behavior:'instant'});}
let returnFocus=null;
function openModal(html){if(!$('#modal').open)returnFocus=document.activeElement;$('#modal-content').innerHTML=html;const heading=$('#modal-content h2');if(heading){heading.id='modal-title';$('#modal').setAttribute('aria-labelledby','modal-title');}if(!$('#modal').open)$('#modal').showModal();else $('.modal-close').focus({preventScroll:true});$('#modal').scrollTop=0;}
function closeModal(){$('#modal').close();if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});}
function openCourse(id){const c=courses.find(x=>x.id===id);if(!c)return;openModal(`<div class="modal-art">${art(c)}</div><div class="course-tags"><span class="pill">${c.categoryLabel}</span><span class="pill pending">โครงร่างหลักสูตร · ยังไม่เปิดรับสมัคร</span></div><h2>${c.title}</h2><p>${c.desc}</p><div class="course-meta" style="margin-top:18px"><span>${icon('clock')}แผนการสอน ${c.hours} ชั่วโมง</span><span>${icon('users')}${c.mode}</span><span>ระดับ${c.level}</span></div><h3 class="modal-subhead">สิ่งที่วางแผนให้คุณได้เรียนรู้</h3><ol class="curriculum">${c.outline.map(t=>`<li>${t}</li>`).join('')}</ol><div class="notice"><strong>สถานะการรับรอง: ยังไม่ได้รับการรับรอง</strong><br>ยังไม่มีเลขอนุมัติหลักสูตร ชั่วโมงรับรอง หรือราคาจำหน่าย ระยะเวลาที่แสดงเป็นแผนเบื้องต้น ไม่สามารถใช้ยื่น CPD หรือต่ออายุใบอนุญาตได้</div><div class="modal-actions"><button class="btn btn-orange" data-add="${c.id}">${plan.includes(c.id)?'อยู่ในแผนการเรียนแล้ว':'เพิ่มในแผนการเรียน'} ${icon('bookmark')}</button><button class="btn btn-line" data-lesson="${c.id}">ทดลองบทเรียน ${icon('play')}</button></div><p class="small-muted" style="margin-top:14px">การเพิ่มในแผนเป็นการบันทึกความสนใจบนเครื่องนี้ ยังไม่ใช่การสมัครเรียน</p>`);}
function addCourse(id){if(!courses.some(c=>c.id===id))return;if(plan.includes(id)){showToast('คอร์สนี้อยู่ในแผนการเรียนแล้ว');return;}plan.push(id);writeStorage('plan',plan);updatePlanCount();const button=$(`[data-add="${id}"]`);if(button)button.innerHTML=`อยู่ในแผนการเรียนแล้ว ${icon('check')}`;showToast('เพิ่มคอร์สในแผนการเรียนแล้ว');}
function lessonContent(c){const content={
 'accounting-foundation':['งบแสดงฐานะการเงินบอกอะไร?','งบแสดงฐานะการเงินช่วยให้เห็นสินทรัพย์ หนี้สิน และส่วนของเจ้าของ ณ วันหนึ่ง ความเชื่อมโยงพื้นฐานคือ สินทรัพย์ = หนี้สิน + ส่วนของเจ้าของ ตัวเลขเหล่านี้ควรอ่านร่วมกับบริบทของกิจการและหมายเหตุประกอบงบการเงิน','ถ้าสินทรัพย์ 100 และหนี้สิน 40 ส่วนของเจ้าของตามสมการพื้นฐานเท่ากับเท่าไร?',['40','60','140'],1,'100 − 40 = 60 เป็นการประยุกต์สมการบัญชีพื้นฐาน'],
 'tax-essentials':['เริ่มที่ข้อเท็จจริง ก่อนเลือกแบบภาษี','ก่อนจัดเตรียมภาษี ควรรู้รูปแบบกิจการ รายการที่เกิดขึ้น สถานะการจดทะเบียน และเอกสารที่มีอยู่จริง ประเด็นที่ไม่ชัดเจนควรตรวจจากแหล่งทางการหรือผู้เชี่ยวชาญที่รับผิดชอบ ไม่สรุปจากชื่อรายการเพียงอย่างเดียว','ก่อนวินิจฉัยประเด็นภาษี ควรเริ่มจากอะไร?',['เลือกคำตอบจากโพสต์ที่แชร์กัน','รวบรวมข้อเท็จจริงและเอกสาร','เดาจากจำนวนเงิน'],1,'ข้อเท็จจริงและเอกสารเป็นจุดเริ่มต้น ก่อนตรวจหลักเกณฑ์ที่เกี่ยวข้อง'],
 'professional-ethics':['ความลับของลูกค้าเป็นเรื่องสำคัญ','ข้อมูลที่ได้จากงานวิชาชีพควรใช้ตามหน้าที่และสิทธิที่ได้รับ กรณีศึกษาเพื่อการเรียนรู้ควรใช้ข้อมูลสมมติหรือจัดการให้เหมาะสม โดยคำนึงถึงหลักเกณฑ์วิชาชีพและข้อกำหนดที่ใช้บังคับ','ควรใช้ข้อมูลแบบใดในแบบฝึกหัดสาธารณะ?',['เอกสารลูกค้าจริงทั้งฉบับ','ข้อมูลสมมติที่ไม่ระบุตัวลูกค้า','รหัสผ่านของลูกค้า'],1,'ข้อมูลสมมติช่วยให้ฝึกคิดได้โดยไม่เปิดเผยข้อมูลของลูกค้า'],
 'excel-accounting':['ตารางที่ดี เริ่มจากข้อมูลที่เป็นระเบียบ','จัดให้หนึ่งแถวแทนหนึ่งรายการ และหนึ่งคอลัมน์แทนข้อมูลประเภทเดียว ตั้งชื่อหัวตารางให้ชัดเจน หลีกเลี่ยงการผสานเซลล์ในชุดข้อมูลดิบ วิธีนี้ช่วยให้กรอง เรียง และสรุปข้อมูลได้ง่าย','โครงสร้างใดเหมาะกับข้อมูลรายการบัญชี?',['รวมทุกข้อมูลไว้ช่องเดียว','หนึ่งแถวต่อหนึ่งรายการ','ผสานเซลล์ทุกแถว'],1,'หนึ่งแถวต่อหนึ่งรายการช่วยให้จัดการและสรุปข้อมูลได้เป็นระบบ'],
 'business-starter':['แยกเงินธุรกิจกับเงินส่วนตัว','การแยกรายการธุรกิจกับรายการส่วนตัวช่วยให้ตรวจสอบที่มาของเงินได้ง่ายขึ้น เริ่มจากกำหนดวิธีบันทึกรายการ เก็บหลักฐานให้ตรงกับธุรกรรม และพูดคุยกับผู้ทำบัญชีเมื่อมีรายการเกี่ยวโยงกัน','วิธีใดช่วยให้ติดตามรายการธุรกิจง่ายขึ้น?',['แยกและเก็บหลักฐานรายการธุรกิจ','ไม่ต้องเก็บหลักฐาน','จำยอดไว้ในใจ'],0,'การแยกและเก็บหลักฐานช่วยให้ผู้รับผิดชอบตรวจสอบรายการย้อนหลังได้'],
 'tax-case-study':['แยกข้อเท็จจริงกับข้อสันนิษฐาน','เมื่ออ่านกรณีศึกษา ให้จดสิ่งที่มีหลักฐานยืนยันแยกจากสิ่งที่คาดเดา ระบุข้อมูลที่ยังขาด แล้วจึงค้นหลักเกณฑ์ที่ตรงกับประเด็น การระบุข้อจำกัดของข้อมูลช่วยให้ข้อสรุปตรวจสอบต่อได้','ถ้าข้อมูลยังไม่ครบ ควรทำอย่างไร?',['ยืนยันคำตอบทันที','ระบุข้อมูลที่ขาดและขอหลักฐานเพิ่ม','เลือกคำตอบที่เสียภาษีน้อยที่สุด'],1,'การหาข้อเท็จจริงเพิ่มช่วยให้ตรวจหลักเกณฑ์และวิเคราะห์ได้ตรงประเด็น']};return content[c.id];}
function openLesson(id,tab='read'){const c=courses.find(x=>x.id===id);if(!c)return;const l=lessonContent(c);const complete=readStorage(`lesson-${id}`,false);openModal(`<div class="eyebrow">ACADEMY / SAMPLE LESSON</div><h2>${c.title}</h2><div class="demo-ribbon">บทเรียนทดลองสั้น ๆ · ไม่ให้ชั่วโมง CPD หรือใบประกาศนียบัตร</div><div class="lesson-nav"><button class="lesson-tab ${tab==='read'?'active':''}" data-lesson-tab="read" data-id="${id}">01 อ่านบทเรียน</button><button class="lesson-tab ${tab==='quiz'?'active':''}" data-lesson-tab="quiz" data-id="${id}">02 ลองทบทวน</button></div>${tab==='read'?`<h3 class="modal-subhead">${l[0]}</h3><p style="font-size:14px;line-height:2;margin-top:15px;color:#66775b">${l[1]}</p><div class="modal-actions"><button class="btn btn-orange" data-lesson-tab="quiz" data-id="${id}">ทบทวนความเข้าใจ <span>↗</span></button></div>`:`<h3 class="modal-subhead">${l[2]}</h3><div id="quiz-options">${l[3].map((o,i)=>`<button class="quiz-option" data-answer="${i}" data-correct="${l[4]}" data-id="${id}">${String.fromCharCode(65+i)}. ${o}</button>`).join('')}</div><div class="quiz-feedback" id="quiz-feedback" aria-live="polite">${complete?'คุณเคยทำตัวอย่างนี้แล้ว ลองทบทวนได้อีกครั้ง':''}</div>`}<div class="modal-actions"><button class="btn btn-line" data-add="${id}">${plan.includes(id)?'อยู่ในแผนการเรียนแล้ว':'บันทึกคอร์สในแผน'} ${icon('bookmark')}</button></div>`);}
function openContact(subject=''){openModal(`<div class="eyebrow">LET’S START A CONVERSATION</div><h2>เล่าเป้าหมายของคุณให้เราฟัง</h2><p>เตรียมข้อมูลสั้น ๆ เพื่อพูดคุยเรื่องบริการหรือการอบรม</p><div class="notice" style="margin-top:16px">เว็บไซต์อยู่ในขั้นต้นแบบ แบบฟอร์มนี้ช่วยจัดข้อความและดาวน์โหลดไว้เท่านั้น ยังไม่มีการส่งข้อมูล นัดหมาย หรือยืนยันรับงาน</div><form id="contact-form"><label class="field">เรื่องที่สนใจ<select id="contact-subject" required>${['บริการทำบัญชี','บริการภาษี','จดทะเบียนธุรกิจ','วางระบบและที่ปรึกษา','หลักสูตร Academy','อบรมสำหรับองค์กร','สอบถามทั่วไป'].map(s=>`<option ${s===subject?'selected':''}>${s}</option>`).join('')}</select></label><div class="field-row"><label class="field">รูปแบบกิจการ / ผู้สนใจ<select id="contact-type"><option>บริษัท / ห้างหุ้นส่วน</option><option>บุคคลธรรมดา / เจ้าของกิจการ</option><option>ผู้ประกอบวิชาชีพบัญชี</option><option>ทีมงาน / องค์กร</option><option>อื่น ๆ</option></select></label><label class="field">ช่วงเวลาที่ต้องการเริ่ม<select id="contact-time"><option>กำลังหาข้อมูล</option><option>ภายใน 1 เดือน</option><option>ภายใน 3 เดือน</option><option>ต้องการวางแผนล่วงหน้า</option></select></label></div><label class="field">สิ่งที่อยากให้ช่วย<textarea id="contact-message" required minlength="10" maxlength="1500" placeholder="เช่น กำลังเริ่มบริษัท อยากวางระบบบัญชีตั้งแต่เดือนแรก"></textarea></label><span class="field-hint">ใช้ข้อมูลภาพรวม หลีกเลี่ยงเลขประจำตัวผู้เสียภาษี รหัสผ่าน และข้อมูลการเงินจริง</span><button class="btn btn-orange" type="submit" style="margin-top:23px;width:100%">สร้างข้อความสำหรับติดต่อ <span>↗</span></button></form><div id="contact-result" aria-live="polite"></div>`);}
function downloadText(text, filename){const url=URL.createObjectURL(new Blob(['\ufeff',text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function privacy(){openModal(`<div class="eyebrow">YOUR INFORMATION MATTERS</div><h2>ความเป็นส่วนตัวในเว็บไซต์ต้นแบบ</h2><p>แผนการเรียนและตัวเลขแผนอบรมที่คุณกดบันทึกจะเก็บไว้ใน localStorage ของเบราว์เซอร์เครื่องนี้ ไม่เชื่อมต่อกับบัญชีสมาชิก และไม่ซิงก์ข้ามอุปกรณ์</p><h3 class="modal-subhead">แบบฟอร์มเตรียมข้อมูลติดต่อ</h3><p style="font-size:13px;line-height:1.9;color:#76846b;margin-top:12px">ข้อความที่พิมพ์ใช้สร้างร่างบนหน้านี้เท่านั้น คุณเลือกดาวน์โหลดเป็นไฟล์ได้ ข้อความจะไม่ถูกส่งให้ทีมงานหรือบันทึกในฐานข้อมูลของ DollarOne</p><h3 class="modal-subhead">บริการภายนอก</h3><p style="font-size:13px;line-height:1.9;color:#76846b;margin-top:12px">เว็บไซต์โหลดฟอนต์จาก Google Fonts และทำงานบนบริการโฮสต์ซึ่งอาจมีบันทึกทางเทคนิคตามเงื่อนไขของผู้ให้บริการ DollarOne ไม่ติดตั้งเครื่องมือวิเคราะห์การตลาดในต้นแบบนี้</p><div class="notice">ก่อนเปิดเว็บไซต์จริง จะต้องจัดทำนโยบายที่ตรงกับผู้ควบคุมข้อมูล ระบบจริง และช่องทางติดต่อที่ยืนยันแล้ว</div><div class="modal-actions"><button class="btn btn-line" id="clear-local-data">ล้างแผนและประวัติทดลองบนเครื่องนี้</button></div>`);}
document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t)return;if(t.matches('.skip-link')){e.preventDefault();$('#main').focus();$('#main').scrollIntoView({behavior:'instant'});return;}if(t.matches('[data-contact]')){openContact(t.dataset.contact);return;}if(t.matches('[data-course]')){openCourse(t.dataset.course);return;}if(t.matches('[data-add]')){addCourse(t.dataset.add);return;}if(t.matches('[data-lesson]')){openLesson(t.dataset.lesson);return;}if(t.matches('[data-lesson-tab]')){openLesson(t.dataset.id,t.dataset.lessonTab);return;}if(t.matches('[data-answer]')){const c=courses.find(x=>x.id===t.dataset.id);const l=lessonContent(c);if(Number(t.dataset.answer)===Number(t.dataset.correct)){t.classList.add('correct');$('#quiz-feedback').textContent=`ถูกต้อง · ${l[5]} การทดลองนี้ไม่ให้ชั่วโมงรับรอง`;writeStorage(`lesson-${c.id}`,true);}else{$('#quiz-feedback').textContent='ลองคิดอีกครั้ง โดยย้อนดูหลักการจากบทเรียนได้';}return;}if(t.matches('[data-remove]')){plan=plan.filter(id=>id!==t.dataset.remove);writeStorage('plan',plan);updatePlanCount();$('#main').innerHTML=renderLearning();showToast('นำคอร์สออกจากแผนแล้ว');return;}if(t.matches('[data-category]')){filters.category=t.dataset.category;$$('[data-category]').forEach(b=>{const a=b===t;b.classList.toggle('active',a);b.setAttribute('aria-pressed',String(a));});filterCatalog();return;}if(t.matches('[data-home-category]')){const cat=t.dataset.homeCategory;$$('[data-home-category]').forEach(b=>{const a=b===t;b.classList.toggle('active',a);b.setAttribute('aria-pressed',String(a));});$('#home-courses').innerHTML=courses.filter(c=>cat==='all'||c.category===cat).slice(0,3).map(courseCard).join('');return;}if(t.id==='clear-filters'){filters={category:'all',role:'all',search:''};$('#main').innerHTML=renderAcademy();filterCatalog();return;}if(t.matches('[data-privacy]')){privacy();return;}if(t.id==='clear-local-data'){try{Object.keys(localStorage).filter(k=>k.startsWith('dollarone-')).forEach(k=>localStorage.removeItem(k));}catch{}memory={};plan=[];updatePlanCount();closeModal();route();showToast('ล้างข้อมูลต้นแบบบนเครื่องนี้แล้ว');return;}if(t.id==='menu-toggle'){const open=$('#navigation').classList.toggle('open');t.setAttribute('aria-expanded',String(open));t.setAttribute('aria-label',open?'ปิดเมนู':'เปิดเมนู');return;}if(t.matches('.modal-close'))closeModal();});
document.addEventListener('input',e=>{if(e.target.id==='course-search'){filters.search=e.target.value;filterCatalog();}if(['cpd-target','cpd-done'].includes(e.target.id))updateCpdSummary();});
document.addEventListener('change',e=>{if(e.target.id==='role-filter'){filters.role=e.target.value;filterCatalog();}});
document.addEventListener('submit',e=>{if(e.target.id==='cpd-form'){e.preventDefault();writeStorage('cpd',{role:$('#cpd-role').value,year:Number($('#cpd-year').value),target:Number($('#cpd-target').value),done:Number($('#cpd-done').value)});showToast('บันทึกแผนส่วนตัวในเบราว์เซอร์แล้ว');}if(e.target.id==='contact-form'){e.preventDefault();const text=`ร่างข้อความสอบถาม DollarOne\n\nเรื่อง: ${$('#contact-subject').value}\nผู้สนใจ: ${$('#contact-type').value}\nช่วงเวลา: ${$('#contact-time').value}\n\nรายละเอียด:\n${$('#contact-message').value}\n\nข้อความนี้จัดทำจากเว็บไซต์ต้นแบบ ยังไม่มีการส่งข้อมูลหรือนัดหมาย`;$('#contact-result').innerHTML=`<div class="success-box"><strong>ร่างข้อความพร้อมแล้ว</strong><p>ยังไม่มีการส่งข้อมูล คุณสามารถดาวน์โหลดร่างไว้ได้</p><pre>${esc(text)}</pre><button class="btn btn-dark btn-sm" type="button" id="download-inquiry">ดาวน์โหลดข้อความ ${icon('download')}</button></div>`;$('#download-inquiry').addEventListener('click',()=>downloadText(text,'DollarOne-inquiry.txt'));$('#contact-result').scrollIntoView({behavior:'smooth',block:'nearest'});}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('#modal').addEventListener('close',()=>{if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});});
window.addEventListener('hashchange',route);
hydrateIcons();updatePlanCount();route();
